package org.telegram.ui;

import android.content.Context;
import android.graphics.*;
import android.os.SystemClock;
import android.view.*;
import android.widget.*;
import androidx.viewpager.widget.PagerAdapter;
import androidx.viewpager.widget.ViewPager;
import org.json.JSONObject;
import org.telegram.messenger.*;
import org.telegram.messenger.devgram.profile.ProfileSlotsStore;
import org.telegram.ui.ActionBar.*;
import org.telegram.ui.Components.*;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** Reference slot overview: real profile captures, side cards, paging and drag-to-delete. */
final class DevGramProfileSlots extends FrameLayout {
    private static final ExecutorService IO=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"devgram-profile-slots");t.setDaemon(true);return t;});
    private final DevGramProfileEditor editor;private final ProfileActivity host;private final ViewGroup decor;
    private JSONObject original;private DevGramProfileStyle.Style originalTheme;private boolean originalDirty;private String initialActive;
    private final long uid;private final int account;private ProfileSlotsStore store;
    private final ViewPager pager;private final TextView title,label;private final ImageView pencil;private final LinearLayout control;
    private final ArrayList<ProfileSlotsStore.Slot> slots=new ArrayList<>();private final HashMap<String,ImageView> cards=new HashMap<>();
    private final LinkedHashMap<String,Bitmap> bitmaps=new LinkedHashMap<>(4,.75f,true);
    private boolean closed,busy,dragging,accepted;private int captureGeneration;private long lastLoad;
    private final Runnable policy=()->{if(!allowed())dismiss(false);};
    private String t(String s){return DevGramLocale.text(s);}private int dp(float n){return AndroidUtilities.dp(n);}
    private boolean allowed(){return !closed&&editor==host.devgramEditor&&host.getCurrentAccount()==account&&host.getUserConfig().getClientUserId()==uid&&DevGramProfileCustomization.enabled();}
    static DevGramProfileSlots show(DevGramProfileEditor editor){if(editor.host.getParentActivity()==null)return null;View view=editor.host.getParentActivity().getWindow().getDecorView();if(!(view instanceof ViewGroup))return null;DevGramProfileSlots overview=new DevGramProfileSlots(editor,(ViewGroup)view);overview.open();return overview;}
    private DevGramProfileSlots(DevGramProfileEditor editor,ViewGroup decor){
        super(decor.getContext());this.editor=editor;host=editor.host;this.decor=decor;uid=editor.uid;account=host.getCurrentAccount();original=DevGramProfileDocument.copy(editor.draft.document);originalTheme=editor.draft.theme;originalDirty=editor.draft.dirty;
        setClickable(true);setFocusableInTouchMode(true);setBackgroundColor(0xff171b23);setPadding(0,AndroidUtilities.statusBarHeight,0,Math.max(AndroidUtilities.navigationBarHeight,dp(18)));
        title=DevGramStudioControls.text(getContext(),"Мои профили",22,true,host.getResourceProvider());title.setGravity(Gravity.CENTER);title.setTextColor(Color.WHITE);addView(title,LayoutHelper.createFrame(-1,64,Gravity.TOP,56,0,56,0));
        ImageView close=new ImageView(getContext());close.setImageResource(R.drawable.ic_ab_back);close.setColorFilter(Color.WHITE);close.setPadding(dp(16),dp(16),dp(16),dp(16));close.setContentDescription(t("Закрыть"));close.setOnClickListener(v->dismiss(false));addView(close,LayoutHelper.createFrame(56,56,Gravity.TOP|Gravity.LEFT));
        pager=new ViewPager(getContext());pager.setClipToPadding(false);pager.setPadding(dp(34),dp(8),dp(34),dp(8));pager.setPageMargin(dp(18));pager.setOffscreenPageLimit(1);addView(pager,LayoutHelper.createFrame(-1,-1,Gravity.FILL,0,68,0,86));pager.setPageTransformer(false,(page,position)->{float scale=1-.08f*Math.min(1,Math.abs(position));page.setScaleX(scale);page.setScaleY(scale);page.setAlpha(1-.3f*Math.min(1,Math.abs(position)));});
        control=new LinearLayout(getContext());control.setGravity(Gravity.CENTER_VERTICAL);control.setPadding(dp(20),0,dp(14),0);control.setBackground(DevGramStudioControls.surface(0x443f4858,0));label=DevGramStudioControls.text(getContext(),"Загрузка…",16,true,host.getResourceProvider());label.setTextColor(Color.WHITE);control.addView(label,new LinearLayout.LayoutParams(0,-2,1));pencil=new ImageView(getContext());pencil.setImageResource(R.drawable.msg_edit);pencil.setColorFilter(Color.WHITE);pencil.setPadding(dp(10),dp(10),dp(10),dp(10));control.addView(pencil,new LinearLayout.LayoutParams(dp(42),dp(42)));control.setOnClickListener(v->rename());addView(control,LayoutHelper.createFrame(-1,48,Gravity.BOTTOM,34,0,34,14));
        pager.addOnPageChangeListener(new ViewPager.SimpleOnPageChangeListener(){@Override public void onPageSelected(int position){page();}});
    }
    static void saveIfInitialized(DevGramProfileEditor editor){
        int account=editor.host.getCurrentAccount();long uid=editor.uid,subject=editor.draft.target(account);JSONObject document=DevGramProfileSlotMedia.snapshot(editor.draft.document,subject),theme=editor.draft.theme==null?new JSONObject():editor.draft.theme.json();
        IO.execute(()->{try{ProfileSlotsStore library=new ProfileSlotsStore(ApplicationLoader.applicationContext.getFilesDir(),account,uid,subject);if(library.slots().isEmpty())return;library.save(document,theme);DevGramProfileSlotMedia.cached(library,document,false);AndroidUtilities.runOnUIThread(()->DevGramProfileSlotMedia.archives(account,library,document,false,IO,null));}catch(Exception error){FileLog.e(error);}});
    }
    private void open(){
        Bitmap capture=editor.slotCapture();decor.addView(this,new ViewGroup.LayoutParams(-1,-1));requestFocus();setAlpha(0);setScaleX(.94f);setScaleY(.94f);animate().alpha(1).scaleX(1).scaleY(1).setDuration(260).setInterpolator(CubicBezierInterpolator.EASE_OUT_QUINT).start();DevGramProfilePolicy.listen(policy);busy=true;
        JSONObject document=snapshotDocument(original);JSONObject theme=originalTheme==null?new JSONObject():originalTheme.json();
        IO.execute(()->{try{ProfileSlotsStore loaded=new ProfileSlotsStore(ApplicationLoader.applicationContext.getFilesDir(),account,uid,editor.draft.target(account));if(loaded.slots().isEmpty())loaded.create(t("Профиль")+" 1",document,theme);else loaded.save(document,theme);initialActive=loaded.active();if(capture!=null)writePreview(loaded,loaded.active(),capture);preserve(loaded,document);AndroidUtilities.runOnUIThread(()->{if(!allowed()){release(capture);return;}store=loaded;DevGramProfileSlotMedia.archives(account,loaded,document,false,IO,null);busy=false;refresh(store.active());if(capture!=null)putBitmap(store.active(),capture);});}catch(Exception error){FileLog.e(error);AndroidUtilities.runOnUIThread(()->{release(capture);if(allowed()){error();dismiss(false);}});}});
    }
    private JSONObject snapshotDocument(JSONObject document){return DevGramProfileSlotMedia.snapshot(document,editor.draft.target(account));}
    private void preserve(ProfileSlotsStore library,JSONObject document)throws Exception{DevGramProfileSlotMedia.cached(library,document,false);}
    private void restore(ProfileSlotsStore library,JSONObject document)throws Exception{DevGramProfileSlotMedia.cached(library,document,true);}
    private static void writePreview(ProfileSlotsStore store,String id,Bitmap image)throws Exception{java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();if(!image.compress(Bitmap.CompressFormat.JPEG,86,bytes))throw new java.io.IOException();store.savePreview(id,bytes.toByteArray());}
    private void refresh(String selected){slots.clear();slots.addAll(store.slots());cards.clear();pager.setAdapter(new PagerAdapter(){public int getCount(){return slots.size()+1;}public boolean isViewFromObject(View v,Object o){return v==o;}public Object instantiateItem(ViewGroup container,int position){View page;if(position==slots.size()){TextView plus=new TextView(getContext());plus.setGravity(Gravity.CENTER);plus.setText("+\n"+t("Создать профиль"));plus.setTextColor(Color.WHITE);plus.setTextSize(24);plus.setBackground(DevGramStudioControls.surface(0x333f4858,0x55778090));plus.setOnClickListener(v->create());page=plus;}else{ProfileSlotsStore.Slot slot=slots.get(position);ImageView image=new ImageView(getContext());image.setScaleType(ImageView.ScaleType.FIT_XY);image.setBackgroundColor(0xff212735);image.setContentDescription(slot.name);image.setClipToOutline(true);image.setOutlineProvider(new ViewOutlineProvider(){public void getOutline(View view,Outline outline){outline.setRoundRect(0,0,view.getWidth(),view.getHeight(),dp(26));}});cards.put(slot.id,image);Bitmap bitmap=bitmaps.get(slot.id);if(bitmap!=null)image.setImageBitmap(bitmap);else loadPreview(slot.id,image);image.setOnClickListener(v->choose(slot.id));drag(image,slot.id);page=image;}container.addView(page,new ViewGroup.LayoutParams(-1,-1));return page;}public void destroyItem(ViewGroup container,int position,Object object){container.removeView((View)object);if(position<slots.size())cards.remove(slots.get(position).id);}});int page=0;for(int i=0;i<slots.size();i++)if(slots.get(i).id.equals(selected))page=i;pager.setCurrentItem(page,false);page();}
    private void loadPreview(String id,ImageView view){IO.execute(()->{BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.RGB_565;Bitmap image=BitmapFactory.decodeFile(store.preview(id).getPath(),options);AndroidUtilities.runOnUIThread(()->{if(!allowed()){release(image);return;}if(image!=null){putBitmap(id,image);if(cards.get(id)==view)view.setImageBitmap(image);}});});}
    private void putBitmap(String id,Bitmap bitmap){if(bitmap==null)return;if(selected()!=null&&selected().id.equals(id)){int color=bitmap.getPixel(Math.max(0,bitmap.getWidth()/2),Math.max(0,bitmap.getHeight()/3));setBackgroundColor(Color.rgb(Color.red(color)*2/3,Color.green(color)*2/3,Color.blue(color)*2/3));}bitmaps.put(id,bitmap);ImageView image=cards.get(id);if(image!=null)image.setImageBitmap(bitmap);while(bitmaps.size()>5){String old=bitmaps.keySet().iterator().next();bitmaps.remove(old);ImageView oldView=cards.get(old);if(oldView!=null)oldView.setImageDrawable(null);/* Native display lists release old captures after their draw. */}}
    private ProfileSlotsStore.Slot selected(){int page=pager.getCurrentItem();return page<slots.size()?slots.get(page):null;}
    private void bind(ProfileSlotsStore.Slot slot){editor.draft.document=DevGramProfileDocument.editable(slot.document());editor.draft.theme=new DevGramProfileStyle.Style(slot.theme());editor.draft.dirty=true;host.devgramRefreshEditor();}
    private void page(){if(!allowed()||busy)return;ProfileSlotsStore.Slot slot=selected();control.setEnabled(slot!=null);label.setText(slot==null?t("Создать профиль"):slot.name);if(slot==null)return;bind(slot);final int generation=++captureGeneration;postDelayed(()->{if(!allowed()||generation!=captureGeneration||dragging)return;Bitmap capture=editor.slotCapture();if(capture==null)return;putBitmap(slot.id,capture);IO.execute(()->{try{writePreview(store,slot.id,capture);}catch(Exception e){FileLog.e(e);}});},700);}
    private void choose(String id){if(!allowed()||busy)return;busy=true;IO.execute(()->{try{ProfileSlotsStore.Slot slot=store.select(id);restore(store,slot.document());AndroidUtilities.runOnUIThread(()->{if(!allowed())return;DevGramProfileSlotMedia.archives(account,store,slot.document(),true,IO,()->{busy=false;if(!allowed())return;bind(slot);accepted=true;dismiss(true);});});}catch(Exception e){FileLog.e(e);AndroidUtilities.runOnUIThread(()->{busy=false;error();});}});}
    private void rename(){ProfileSlotsStore.Slot slot=selected();if(slot==null||busy)return;EditText input=new EditText(getContext());input.setText(slot.name);input.setTextColor(Theme.getColor(Theme.key_dialogTextBlack,host.getResourceProvider()));input.setSingleLine(true);input.setSelectAllOnFocus(true);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(128)});new AlertDialog.Builder(getContext(),host.getResourceProvider()).setTitle(t("Название профиля")).setView(input).setPositiveButton(t("Сохранить"),(d,w)->mutate(()->store.rename(slot.id,input.getText().toString()),slot.id)).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).show();}
    private interface Mutation{void run()throws Exception;}
    private void mutate(Mutation action,String selected){if(busy||!allowed())return;busy=true;IO.execute(()->{try{action.run();AndroidUtilities.runOnUIThread(()->{busy=false;if(allowed())refresh(selected==null?store.active():selected);});}catch(Exception e){FileLog.e(e);AndroidUtilities.runOnUIThread(()->{busy=false;error();});}});}
    private void create(){if(!allowed()||busy)return;new AlertDialog.Builder(getContext(),host.getResourceProvider()).setTitle(t("Создать профиль")).setItems(new CharSequence[]{t("Пустой профиль"),t("Из текущего оформления")},(dialog,which)->{JSONObject doc=which==0?new JSONObject():snapshotDocument(original),theme=which==0?new JSONObject():originalTheme==null?new JSONObject():originalTheme.json();mutate(()->{store.create(t("Профиль")+" "+(slots.size()+1),doc,theme);preserve(store,doc);},null);}).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).show();}
    private void remove(String id){if(!allowed()||busy)return;if(slots.size()<=1){new AlertDialog.Builder(getContext(),host.getResourceProvider()).setMessage(t("Последний профиль нельзя удалить.")).setPositiveButton(t("Понятно"),null).show();return;}String fallback=null;for(ProfileSlotsStore.Slot slot:slots)if(!slot.id.equals(id)){fallback=slot.id;break;}final String next=fallback;new AlertDialog.Builder(getContext(),host.getResourceProvider()).setTitle(t("Удалить профиль?")).setMessage(t("Сохранённый вариант будет удалён с этого устройства." )).setPositiveButton(t("Удалить"),(d,w)->mutate(()-> {store.remove(id,next);if(id.equals(initialActive)){ProfileSlotsStore.Slot fallbackSlot=store.get(next);initialActive=next;original=fallbackSlot.document();originalTheme=new DevGramProfileStyle.Style(fallbackSlot.theme());originalDirty=true;}},next)).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).show();}
    private void drag(ImageView image,String id){final float[] start={0,0};final boolean[] active={false};Runnable hold=()->{if(busy||!allowed())return;active[0]=dragging=true;captureGeneration++;image.getParent().requestDisallowInterceptTouchEvent(true);image.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);image.animate().scaleX(.94f).scaleY(.94f).setDuration(160).start();pencil.animate().scaleX(0).scaleY(0).setDuration(80).withEndAction(()->{pencil.setImageResource(R.drawable.msg_delete);pencil.setColorFilter(0xffff7474);pencil.animate().scaleX(1).scaleY(1).setDuration(140).start();}).start();label.setText(t("Перетащите сюда, чтобы удалить"));};image.setOnTouchListener((view,event)->{switch(event.getActionMasked()){case MotionEvent.ACTION_DOWN:start[0]=event.getRawX();start[1]=event.getRawY();image.postDelayed(hold,400);break;case MotionEvent.ACTION_MOVE:float dx=event.getRawX()-start[0],dy=event.getRawY()-start[1];if(active[0]){image.setTranslationX(dx);image.setTranslationY(dy);return true;}if(Math.hypot(dx,dy)>dp(8))image.removeCallbacks(hold);break;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:image.removeCallbacks(hold);if(active[0]){active[0]=dragging=false;int[] where=new int[2];control.getLocationOnScreen(where);boolean drop=event.getActionMasked()==MotionEvent.ACTION_UP&&event.getRawY()>=where[1]-dp(20);image.animate().translationX(0).translationY(0).scaleX(1).scaleY(1).setDuration(220).setInterpolator(CubicBezierInterpolator.EASE_OUT_QUINT).start();pencil.setImageResource(R.drawable.msg_edit);pencil.setColorFilter(Color.WHITE);if(selected()!=null)label.setText(selected().name);if(drop)remove(id);return true;}break;}return false;});}
    private void error(){if(allowed())BulletinFactory.of(host).createErrorBulletin(t("Не удалось сохранить профили. Проверьте свободное место.")).show();}
    private static void release(Bitmap image){if(image!=null&&!image.isRecycled())image.recycle();}
    void dismiss(boolean keep){if(closed)return;closed=true;captureGeneration++;DevGramProfilePolicy.unlisten(policy);if(!keep&&!accepted){if(store!=null&&store.get(initialActive)!=null)IO.execute(()->{try{store.select(initialActive);}catch(Exception error){FileLog.e(error);}});editor.draft.document=original;editor.draft.theme=originalTheme;editor.draft.dirty=originalDirty;if(editor==host.devgramEditor)host.devgramRefreshEditor();}animate().alpha(0).scaleX(.96f).scaleY(.96f).setDuration(220).withEndAction(()->{decor.removeView(this);cards.clear();bitmaps.clear();}).start();editor.slotsClosed(this);}
    @Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getKeyCode()==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP)dismiss(false);return true;}return super.dispatchKeyEvent(event);}
}
